/* QA E2E — DOOM Clone Three.js (R29: testar como usuário final) */
import { chromium } from 'playwright';

const EXE = '/home/johncoffee/.cache/ms-playwright/chromium-1234/chrome-linux64/chrome';
const OUT = '/tmp/opencode/doom-qa';
const BASE = 'http://localhost:8765/';

const browser = await chromium.launch({
  executablePath: EXE,
  headless: true,
  args: ['--enable-unsafe-swiftshader', '--use-angle=swiftshader', '--enable-webgl', '--no-sandbox', '--disable-gpu-sandbox'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });

const consoleErrors = [];
const pageErrors = [];
page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(m.text()); });
page.on('pageerror', (e) => pageErrors.push(e.message));

const results = [];
const check = (name, ok, detail = '') => {
  results.push({ name, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'} | ${name}${detail ? ' | ' + detail : ''}`);
};

// 1. carregar
await page.goto(BASE, { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
check('página carrega', await page.title() === 'DOOM CLONE — Three.js', await page.title());

// 2. WebGL ativo?
const webgl = await page.evaluate(() => {
  const c = document.createElement('canvas');
  return !!(c.getContext('webgl2') || c.getContext('webgl'));
});
check('WebGL disponível', webgl);

// 3. menu visível
const menuShown = await page.isVisible('#menu-screen.show');
check('menu visível', menuShown);
await page.screenshot({ path: `${OUT}/01-menu.png` });

// 4. iniciar
await page.click('#btn-start');
await page.waitForTimeout(1200);

// 5. estado e debug API
const s0 = await page.evaluate(() => {
  if (!window.__game) return null;
  const g = window.__game;
  const st = g.getState();
  return { state: g.state, hp: st.player.health, armor: st.player.armor, weapon: st.weapons.name,
           ammo: st.weapons.ammo, kills: st.player.kills, fps: st.fps,
           enemies: st.enemies.length, x: st.player.x, z: st.player.z, alive: st.player.alive };
});
check('debug API __game existe', !!s0);
check('estado playing', s0?.state === 'playing', JSON.stringify(s0?.state));
check('jogador vivo (hp=100)', s0?.hp === 100, `hp=${s0?.hp}`);
check('arma inicial pistol', s0?.weapon === 'PISTOL', s0?.weapon);
check('inimigos spawnados', (s0?.enemies ?? 0) >= 3, `n=${s0?.enemies}`);
check('HUD health mostra 100', await page.textContent('#health-num') === '100', await page.textContent('#health-num'));
check('HUD ammo presente', (await page.textContent('#ammo-num')).trim().length > 0);

// 6. screenshot gameplay (sala inicial)
await page.screenshot({ path: `${OUT}/02-gameplay-spawn.png` });
await page.waitForTimeout(1000);
const s1 = await page.evaluate(() => window.__game.getState());
check('FPS rodando', (s1?.fps ?? 0) > 0, `fps=${s1?.fps}`);

// 7. trocar arma (shotgun) via debug
await page.evaluate(() => { window.__game.giveAmmo('shell', 30); window.__game.setWeapon(1); });
await page.waitForTimeout(300);
const s2 = await page.evaluate(() => window.__game.getState());
check('troca para SHOTGUN', s2.weapons.name === 'SHOTGUN', s2.weapons.name);
check('munição shotgun dada', s2.weapons.ammo.shell >= 30, JSON.stringify(s2.weapons.ammo));

// 8. atirar: mousedown no canvas (pistol/shotgun)
await page.evaluate(() => {
  const c = document.getElementById('game-canvas');
  c.dispatchEvent(new MouseEvent('mousedown', { button: 0, bubbles: true }));
});
await page.waitForTimeout(300);
await page.evaluate(() => {
  const c = document.getElementById('game-canvas');
  c.dispatchEvent(new MouseEvent('mouseup', { button: 0, bubbles: true }));
});
await page.waitForTimeout(200);
const shot = await page.evaluate(() => { const g = window.__game.getState(); return { shell: g.weapons.ammo.shell, shotsFired: g.player.shotsFired ?? -1 }; });
check('disparo consome munição', shot.shell === 29, `shell=${shot.shell}`);
await page.screenshot({ path: `${OUT}/03-after-shot.png` });

// 9. minimap existe e desenhando (não todo preto)
const minimapPx = await page.evaluate(() => {
  const c = document.getElementById('minimap');
  const ctx = c.getContext('2d');
  const d = ctx.getImageData(0, 0, c.width, c.height).data;
  let nonBlack = 0;
  for (let i = 0; i < d.length; i += 40) if (d[i] + d[i + 1] + d[i + 2] > 30) nonBlack++;
  return nonBlack;
});
check('minimap renderiza pixels', minimapPx > 50, `pixels não-pretos=${minimapPx}`);

// 10. teleport perto de inimigo vivo + screenshot da luta
const target = await page.evaluate(() => {
  const g = window.__game.getState();
  const alive = g.enemies.find((e) => !e.dead);
