  const g = window.__game;
  return { yaw: g.engine.camera.rotation.y, pitch: g.engine.camera.rotation.x, order: g.engine.camera.rotation.order,
           player: { x: g.getState().player.x, z: g.getState().player.z } };
});
console.log('INIT:', JSON.stringify(init));

// yaw imediatamente após lookAt (mesmo evaluate)
const look = await page.evaluate(() => {
  const g = window.__game;
  const st = g.getState();
  const t = st.enemies.find((e) => !e.dead);
  g.teleport(t.x + 2.5, t.z + 0.5);
  g.engine.camera.lookAt(t.x, 1.2, t.z);
  return { yaw: +g.engine.camera.rotation.y.toFixed(4), pitch: +g.engine.camera.rotation.x.toFixed(4),
           quatY: +g.engine.camera.quaternion.y.toFixed(4) };
});
console.log('LOOK imediato:', JSON.stringify(look));

// yaw após 500ms de frames
