  const g = window.__game;
  return { yaw: +g.engine.camera.rotation.y.toFixed(4), pitch: +g.engine.camera.rotation.x.toFixed(4),
           mx: g.engine.input.mx, my: g.engine.input.my };
});
console.log('AFTER 500ms:', JSON.stringify(after));

// ROTAÇÃO DIRETA (determinística) + tiro + dano no alvo específico
const shot = await page.evaluate(() => {
  const g = window.__game;
  const st = g.getState();
  const t = st.enemies.find((e) => !e.dead);
  const p = st.player;
  const cam = g.engine.camera;
  // vetor câmera→alvo
  const dx = t.x - cam.position.x, dy = 1.2 - cam.position.y, dz = t.z - cam.position.z;
  const len = Math.hypot(dx, dy, dz);
  const nx = dx / len, ny = dy / len, nz = dz / len;
  const yaw = Math.atan2(-nx, -nz);
  const pitch = Math.asin(ny);
  cam.rotation.set(pitch, yaw, 0);
  const before = { hp: t.hp, x: t.x, z: t.z };
  // atira segurando 1.2s
  const c = document.getElementById('game-canvas');
  c.dispatchEvent(new MouseEvent('mousedown', { button: 0, bubbles: true }));
