check('encontro inimigo vivo', !!target, JSON.stringify(target));
if (target) {
  // achar célula livre adjacente ao alvo (LOS garantido, sem parede/lava)
  const losPos = await page.evaluate((t) => {
    const g = window.__game;
    const map = g.map;
    const offsets = [[1.5, 0], [-1.5, 0], [0, 1.5], [0, -1.5], [1.5, 1.5], [-1.5, 1.5], [1.5, -1.5], [-1.5, -1.5]];
    for (const [dx, dz] of offsets) {
      const x = t.x + dx, z = t.z + dz;
      if (map.isSolid(Math.floor(z), Math.floor(x)) || map.isLava(Math.floor(z), Math.floor(x))) continue;
      return { x, z };
    }
    return null;
  }, target);
  if (losPos) {
    // teleport + espera a câmera acompanhar (1 frame) + lookAt com timing correto
    await page.evaluate((p) => window.__game.teleport(p.x, p.z), losPos);
    await page.waitForTimeout(120);
    await page.evaluate((t) => { window.__game.engine.camera.lookAt(t.x, 1.2, t.z); }, target);
    await page.waitForTimeout(250);
    await page.screenshot({ path: `${OUT}/04-enemy.png` });
    // atirar: segurar o botão (full-auto respeita cadência) ~1.3s
    const before = await page.evaluate(() => {
      const g = window.__game.getState();
      return { alive: g.enemies.filter((e) => !e.dead).length, kills: g.player.kills };
    });
    await page.evaluate(() => {
      document.getElementById('game-canvas').dispatchEvent(new MouseEvent('mousedown', { button: 0, bubbles: true }));
    });
    await page.waitForTimeout(1300);
    await page.evaluate(() => {
      document.getElementById('game-canvas').dispatchEvent(new MouseEvent('mouseup', { button: 0, bubbles: true }));
    });
    await page.waitForTimeout(400);
    const postKill = await page.evaluate(() => {
      const g = window.__game.getState();
      return { kills: g.player.kills, enemies: g.enemies, state: g.state };
    });
    const aliveNow = postKill.enemies.filter((e) => !e.dead).length;
    check('disparos reduzem inimigos vivos ou matam', aliveNow < before.alive || postKill.kills > before.kills, `vivos ${before.alive}→${aliveNow}, kills ${before.kills}→${postKill.kills}`);
    await page.screenshot({ path: `${OUT}/05-after-fight.png` });
  } else {
    check('disparos reduzem inimigos vivos ou matam', false, 'sem célula livre para teleporte');
  }
}

