  const weaponName = $('weapon-name');
  const killsNum = $('kills-num');
  const messagesEl = $('messages');
  const crosshair = $('crosshair');
  const vignette = $('vignette');
  const crt = $('crt');
  const fpsEl = $('fps');

  let messages = [];
  let msgTimer = 0;
  let damageFlash = 0;

  function pushMessage(text) {
    messages.push(text);
    if (messages.length > 3) messages.shift();
    msgTimer = 3;
  }

  function flashDamage(amount) {
    damageFlash = Math.min(1, damageFlash + amount / 60);
    // Classe CSS dispara o pulso de vignette (sem escrita de estilo por frame).
    if (vignette) vignette.classList.add('active');
  }

  function update(dt) {
    const st = getState();
    if (!st) return;
    const { player, weapons, fps } = st;

    if (healthBar && healthNum) {
      const hp = Math.max(0, Math.round(player.health));
      healthBar.style.width = `${hp}%`;
      healthBar.style.background = hp > 40 ? '#5a9a44' : hp > 20 ? '#ccaa33' : '#cc3333';
      healthNum.textContent = String(hp);
    }
    if (armorBar && armorNum) {
      armorBar.style.width = `${Math.max(0, Math.round(player.armor))}%`;
      armorNum.textContent = String(Math.round(player.armor));
    }
    if (ammoNum) {
      const w = weapons.current !== null ? weapons.ammo[weapons.current] : 0;
      ammoNum.textContent = weapons.current === 'pistol' ? '∞' : String(w ?? 0);
    }
    if (weaponName) weaponName.textContent = (weapons.name || 'PISTOL').toUpperCase();
    if (killsNum) killsNum.textContent = String(player.kills || 0);

    if (msgTimer > 0) {
      msgTimer -= dt;
      if (messagesEl) messagesEl.innerHTML = messages.map((m) => `<div>${m}</div>`).join('');
    } else if (messagesEl) messagesEl.innerHTML = '';

    if (damageFlash > 0) {
      damageFlash = Math.max(0, damageFlash - dt * 1.5);
      if (damageFlash <= 0 && vignette) vignette.classList.remove('active');
    }

    if (crosshair) {
      // getState() não expõe o estado FSM; `locked` (pointer lock) é o proxy
      // de "jogando": só exibe a mira com o mouse travado.
      crosshair.style.opacity = st.locked ? '1' : '0';
      crosshair.classList.toggle('locked', !!st.locked);
    }
    if (fpsEl && fps) fpsEl.textContent = String(fps.value);
  }

  return { update, pushMessage, flashDamage };
}

export default createHUD;
