function frame() {
  requestAnimationFrame(frame);
  const now = performance.now();
  const dt = Math.min((now - last) / 1000, 0.05);
  last = now;
  fpsAcc += dt; fpsFrames++;
  if (fpsAcc >= 1) { fps.value = Math.round(fpsFrames / fpsAcc); fpsAcc = 0; fpsFrames = 0; }
  // auto-relock: se wantLock e pointer lock perdido, tenta re-lockar a cada 800ms
  if (input.wantLock && !input.locked && now - lastLockAttempt > 800) {
    requestLock();
  }
  update(dt);
  onFrame?.(dt);
  renderer.render(scene, camera);
}

