/* Passada de grime: mancha levemente pixels determinísticos (sujeira DOOM). */
function grimePass(ctx, w, h, t, strength = 0.07, seed = 7) {
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const r = hash2(x, y, seed);
      if (r > strength) continue;
      const i = (y * w + x) * 4;
      const f = 0.62 + hash2(x, y, seed + 1) * 0.55;
      d[i] = Math.max(0, Math.min(255, d[i] * f));
      d[i + 1] = Math.max(0, Math.min(255, d[i + 1] * f));
      d[i + 2] = Math.max(0, Math.min(255, d[i + 2] * f));
    }
  }
  ctx.putImageData(img, 0, 0);
}

function noisePass(ctx, w, h,强度 = 0.15, seed = 42) {
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const n = (hash2(x, y, seed) - 0.5) * 強度 * 255;
      const i = (y * w + x) * 4;
      d[i] = Math.max(0, Math.min(255, d[i] + n));
      d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + n));
      d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + n));
    }
  }
  ctx.putImageData(img, 0, 0);
}

function stainPass(ctx, w, h, count = 12, seed = 99) {
  for (let k = 0; k < count; k++) {
    const sx = hash2(k, 0, seed) * w;
    const sy = hash2(k, 1, seed) * h;
    const sr = 6 + hash2(k, 2, seed) * 20;
    const dark = hash2(k, 3, seed) > 0.5;
    const grad = ctx.createRadialGradient(sx, sy, 0, sx, sy, sr);
    if (dark) {
      grad.addColorStop(0, 'rgba(0,0,0,0.25)');
      grad.addColorStop(1, 'rgba(0,0,0,0)');
    } else {
      grad.addColorStop(0, 'rgba(80,70,60,0.15)');
      grad.addColorStop(1, 'rgba(80,70,60,0)');
    }
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(sx, sy, sr, 0, 7); ctx.fill();
  }
}

