  color += vec3(1.0, 0.8, 0.2) * fire * 0.5;
  color += vec3(1.0, 0.95, 0.8) * pow(fire, 3.0) * 0.3;

  float alpha = fire * 0.9;

  gl_FragColor = vec4(color, alpha);
