  background: var(--doom-black);
  color: var(--doom-text);
  font-family: var(--font-mono);
  user-select: none;
  -webkit-user-select: none;
}

/* ---------- Canvas do jogo ---------- */
#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: var(--doom-black);
}

/* ---------- Camada CRT / scanlines ---------- */
#crt-overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.06) 0px,
    rgba(255, 255, 255, 0.06) 1px,
    transparent 1px,
    transparent 3px
  );
  opacity: 0.06;
}

/* ---------- Overlays de tela cheia ---------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.2rem;
  text-align: center;
  background: var(--doom-black);
}

.overlay h2 {
  font-size: 3rem;
  letter-spacing: 0.15em;
  color: var(--doom-blood-bright);
  text-shadow: 0 0 18px rgba(255, 0, 0, 0.8), 0 0 40px rgba(255, 0, 0, 0.4);
}

.hidden {
  display: none !important;
}

/* ---------- Menu ---------- */
#menu .title {
  font-size: 5rem;
  font-weight: 900;
  letter-spacing: 0.2em;
  color: var(--doom-blood);
  text-shadow:
    0 0 12px rgba(255, 0, 0, 0.9),
    0 0 40px rgba(255, 0, 0, 0.6),
    0 4px 0 #400000;
  text-transform: uppercase;
}

