// ES module wrapper - exporta createEnemies para compatibilidade com main.js
function createEnemies(scene, map, hooks) {
  const mod = window.__mods?.enemies || {};
  if (!mod.list) mod.list = [];
  // Wrapper para update que passa game/engine corretamente
  const origUpdate = mod.update;
  mod.update = function(dt, game, engine) {
    if (!game) game = hooks;
    if (!engine) engine = { scene };
    return origUpdate.call(mod, dt, game, engine);
  };
  return mod;
}

