// ES module wrapper - exporta createWeapons para compatibilidade com main.js
function createWeapons(engine, player, hooks) {
  const mod = window.__mods?.weapons || {};
  // Inicializa o módulo se não foi inicializado
  if (!mod._initialized && mod.init) {
    // Cria objeto game simplificado para o init
    const game = { scene: engine.scene, player, weapons: null, events: {}, stats: {} };
    mod.init(game, engine);
    mod._initialized = true;
    // Copia weapons para o mod para acesso externo
    Object.assign(mod, game.weapons);
  }
  return mod;
}

